impl Solution {
    pub fn detect_capital_use(word: String) -> bool {
        let n = word.len();
        if n == 0 {
            return true;
        }

        let mut all_caps = true;
        for c in word.chars() {
            if !c.is_uppercase() {
                all_caps = false;
                break;
            }
        }

        if all_caps {
            return true;
        }

        let mut all_lower = true;
        for c in word.chars() {
            if !c.is_lowercase() {
                all_lower = false;
                break;
            }
        }

        if all_lower {
            return true;
        }

        let mut first_cap_rest_lower = false;
        if word.chars().nth(0).unwrap().is_uppercase() {
            let mut rest_lower = true;
            for c in word.chars().skip(1) {
                if !c.is_lowercase() {
                    rest_lower = false;
                    break;
                }
            }
            if rest_lower {
                first_cap_rest_lower = true;
            }
        }

        all_caps || all_lower || first_cap_rest_lower
    }
}

